import uuid
from django.db import models
from django.db.models import Q

class TransactionStatus(models.TextChoices):
    DRAFT="DRAFT","Bản nháp";PENDING_APPROVAL="PENDING_APPROVAL","Chờ phê duyệt";APPROVED="APPROVED","Đã duyệt";REJECTED="REJECTED","Bị từ chối";POSTED="POSTED","Có hiệu lực";REVERSED="REVERSED","Đã đảo";CANCELLED="CANCELLED","Đã hủy"

class GlStatus(models.TextChoices):
    PENDING="PENDING","Chờ hạch toán";POSTED="POSTED","Đã hạch toán";ERROR="ERROR","Lỗi"
class TransferStatus(models.TextChoices):
    DRAFT="DRAFT","Bản nháp";IN_TRANSIT="IN_TRANSIT","Đang chuyển";CONFIRMED="CONFIRMED","Đã nhận";CANCELLED="CANCELLED","Đã hủy"
class AdvanceStatus(models.TextChoices):
    DRAFT="DRAFT","Bản nháp";PENDING_APPROVAL="PENDING_APPROVAL","Chờ duyệt";APPROVED="APPROVED","Đã duyệt";ACTIVE="ACTIVE","Đang mở";PARTIAL="PARTIAL","Quyết toán một phần";CLOSED="CLOSED","Đã đóng";REJECTED="REJECTED","Từ chối"
class CountStatus(models.TextChoices):
    DRAFT="DRAFT","Bản nháp";CONFIRMED="CONFIRMED","Đã xác nhận";ADJUSTED="ADJUSTED","Đã xử lý"
class FundStatus(models.TextChoices):
    ACTIVE="ACTIVE","Hoạt động";INACTIVE="INACTIVE","Ngừng"

class CashFund(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);company=models.ForeignKey("organization.Company",on_delete=models.PROTECT,related_name="cash_funds");branch=models.ForeignKey("organization.Branch",on_delete=models.PROTECT,related_name="cash_funds");code=models.CharField(max_length=50);name=models.CharField(max_length=255);currency=models.ForeignKey("master_data.Currency",on_delete=models.PROTECT);keeper=models.ForeignKey("organization.Employee",on_delete=models.PROTECT,null=True,blank=True,related_name="managed_cash_funds");gl_account=models.ForeignKey("general_ledger.Account",on_delete=models.PROTECT,related_name="cash_funds");balance=models.DecimalField(max_digits=20,decimal_places=4,default=0);allow_negative=models.BooleanField(default=False);status=models.CharField(max_length=20,choices=FundStatus.choices,default=FundStatus.ACTIVE);created_at=models.DateTimeField(auto_now_add=True);updated_at=models.DateTimeField(auto_now=True)
    class Meta:
        db_table="cash_fund";ordering=("company_id","code");constraints=[models.UniqueConstraint(fields=("company","code"),name="uq_cash_fund_code"),models.CheckConstraint(condition=Q(balance__gte=0)|Q(allow_negative=True),name="ck_cash_fund_nonnegative")]

class CashTransaction(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);company=models.ForeignKey("organization.Company",on_delete=models.PROTECT);fund=models.ForeignKey(CashFund,on_delete=models.PROTECT,related_name="transactions");number=models.CharField(max_length=80);transaction_type=models.CharField(max_length=20,choices=(("RECEIPT","Phiếu thu"),("PAYMENT","Phiếu chi"),("ADVANCE","Chi tạm ứng"),("ADVANCE_RETURN","Hoàn tạm ứng"),("ADJUSTMENT_IN","Điều chỉnh tăng"),("ADJUSTMENT_OUT","Điều chỉnh giảm")));business_type=models.CharField(max_length=50);transaction_date=models.DateField();party=models.ForeignKey("master_data.Party",on_delete=models.PROTECT,null=True,blank=True);payer_payee=models.CharField(max_length=255);currency=models.ForeignKey("master_data.Currency",on_delete=models.PROTECT);amount=models.DecimalField(max_digits=20,decimal_places=4);exchange_rate=models.DecimalField(max_digits=20,decimal_places=8,default=1);base_amount=models.DecimalField(max_digits=20,decimal_places=4);description=models.CharField(max_length=500);attachments=models.JSONField(default=list,blank=True);status=models.CharField(max_length=30,choices=TransactionStatus.choices,default=TransactionStatus.DRAFT);approval_required=models.BooleanField(default=True);workflow_snapshot=models.JSONField(default=dict,blank=True);balance_applied=models.BooleanField(default=False);gl_status=models.CharField(max_length=20,choices=GlStatus.choices,default=GlStatus.PENDING);gl_reference=models.CharField(max_length=120,blank=True);source_module=models.CharField(max_length=20,blank=True);source_reference=models.CharField(max_length=120,blank=True);created_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT,related_name="cash_transactions_created");cashier=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT,null=True,blank=True,related_name="cash_transactions_confirmed");submitted_at=models.DateTimeField(null=True,blank=True);approved_at=models.DateTimeField(null=True,blank=True);posted_at=models.DateTimeField(null=True,blank=True);created_at=models.DateTimeField(auto_now_add=True);updated_at=models.DateTimeField(auto_now=True)
    class Meta:
        db_table="cash_transaction";ordering=("-transaction_date","-created_at");constraints=[models.UniqueConstraint(fields=("company","number"),name="uq_cash_transaction_number"),models.CheckConstraint(condition=Q(amount__gt=0,exchange_rate__gt=0,base_amount__gt=0),name="ck_cash_transaction_amounts")]
    payment_method_config=models.ForeignKey("master_data.PaymentMethod",on_delete=models.PROTECT,null=True,blank=True,related_name="cash_transactions")
    payment_method_snapshot=models.JSONField(default=dict,blank=True)
    receipt_details=models.JSONField(default=dict,blank=True)

class ApprovalDecision(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);company=models.ForeignKey("organization.Company",on_delete=models.PROTECT,related_name="cash_approvals");transaction=models.ForeignKey(CashTransaction,on_delete=models.PROTECT,related_name="approval_decisions");level=models.PositiveSmallIntegerField(default=1);decision=models.CharField(max_length=20,choices=(("SUBMITTED","Đã gửi"),("APPROVED","Phê duyệt"),("REJECTED","Từ chối")));actor=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT,related_name="cash_approvals");comment=models.CharField(max_length=1000,blank=True);decided_at=models.DateTimeField(auto_now_add=True)
    class Meta:db_table="cash_approval";ordering=("decided_at",)

class CashTransfer(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);company=models.ForeignKey("organization.Company",on_delete=models.PROTECT);number=models.CharField(max_length=80);transfer_type=models.CharField(max_length=30,choices=(("FUND_TO_FUND","Giữa các quỹ"),("CASH_TO_BANK","Nộp vào ngân hàng"),("BANK_TO_CASH","Rút từ ngân hàng")));source_fund=models.ForeignKey(CashFund,on_delete=models.PROTECT,null=True,blank=True,related_name="outgoing_transfers");destination_fund=models.ForeignKey(CashFund,on_delete=models.PROTECT,null=True,blank=True,related_name="incoming_transfers");bank_account=models.ForeignKey("master_data.CompanyBankAccount",on_delete=models.PROTECT,null=True,blank=True);transfer_date=models.DateField();amount=models.DecimalField(max_digits=20,decimal_places=4);exchange_rate=models.DecimalField(max_digits=20,decimal_places=8,default=1);bank_reference=models.CharField(max_length=120,blank=True);description=models.CharField(max_length=500);status=models.CharField(max_length=20,choices=TransferStatus.choices,default=TransferStatus.DRAFT);dispatched_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT,null=True,blank=True,related_name="cash_transfers_dispatched");received_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT,null=True,blank=True,related_name="cash_transfers_received");created_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT,related_name="cash_transfers_created");created_at=models.DateTimeField(auto_now_add=True);updated_at=models.DateTimeField(auto_now=True)
    class Meta:db_table="cash_transfer";constraints=[models.UniqueConstraint(fields=("company","number"),name="uq_cash_transfer_number"),models.CheckConstraint(condition=Q(amount__gt=0,exchange_rate__gt=0),name="ck_cash_transfer_amounts")]

class CashAdvance(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);company=models.ForeignKey("organization.Company",on_delete=models.PROTECT);number=models.CharField(max_length=80);fund=models.ForeignKey(CashFund,on_delete=models.PROTECT);recipient=models.ForeignKey("organization.Employee",on_delete=models.PROTECT,related_name="cash_advances");purpose=models.CharField(max_length=500);request_date=models.DateField();due_date=models.DateField(null=True,blank=True);amount=models.DecimalField(max_digits=20,decimal_places=4);settled_amount=models.DecimalField(max_digits=20,decimal_places=4,default=0);returned_amount=models.DecimalField(max_digits=20,decimal_places=4,default=0);additional_paid=models.DecimalField(max_digits=20,decimal_places=4,default=0);status=models.CharField(max_length=20,choices=AdvanceStatus.choices,default=AdvanceStatus.DRAFT);workflow_snapshot=models.JSONField(default=dict,blank=True);disbursement=models.OneToOneField(CashTransaction,on_delete=models.PROTECT,null=True,blank=True,related_name="advance");created_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT);created_at=models.DateTimeField(auto_now_add=True);updated_at=models.DateTimeField(auto_now=True)
    class Meta:db_table="cash_advance";constraints=[models.UniqueConstraint(fields=("company","number"),name="uq_cash_advance_number"),models.CheckConstraint(condition=Q(amount__gt=0,settled_amount__gte=0,returned_amount__gte=0,additional_paid__gte=0),name="ck_cash_advance_amounts")]
    @property
    def remaining_amount(self):return max(self.amount-self.settled_amount-self.returned_amount,0)

class AdvanceSettlement(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);advance=models.ForeignKey(CashAdvance,on_delete=models.PROTECT,related_name="settlements");settlement_date=models.DateField();accepted_expense=models.DecimalField(max_digits=20,decimal_places=4);returned_cash=models.DecimalField(max_digits=20,decimal_places=4,default=0);additional_cash=models.DecimalField(max_digits=20,decimal_places=4,default=0);documents=models.JSONField(default=list,blank=True);note=models.CharField(max_length=500,blank=True);created_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT);created_at=models.DateTimeField(auto_now_add=True)
    class Meta:db_table="cash_advance_settlement";constraints=[models.CheckConstraint(condition=Q(accepted_expense__gte=0,returned_cash__gte=0,additional_cash__gte=0),name="ck_cash_settlement_amounts")]

class CashCount(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);company=models.ForeignKey("organization.Company",on_delete=models.PROTECT);number=models.CharField(max_length=80);fund=models.ForeignKey(CashFund,on_delete=models.PROTECT,related_name="counts");counted_at=models.DateTimeField();book_balance=models.DecimalField(max_digits=20,decimal_places=4,default=0);actual_balance=models.DecimalField(max_digits=20,decimal_places=4);difference=models.DecimalField(max_digits=20,decimal_places=4,default=0);denominations=models.JSONField(default=list,blank=True);reason=models.CharField(max_length=500,blank=True);conclusion=models.CharField(max_length=500,blank=True);status=models.CharField(max_length=20,choices=CountStatus.choices,default=CountStatus.DRAFT);adjustment=models.OneToOneField(CashTransaction,on_delete=models.PROTECT,null=True,blank=True,related_name="cash_count");created_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT);created_at=models.DateTimeField(auto_now_add=True)
    class Meta:db_table="cash_count";constraints=[models.UniqueConstraint(fields=("company","number"),name="uq_cash_count_number")]

class FxRevaluation(models.Model):
    id=models.UUIDField(primary_key=True,default=uuid.uuid4,editable=False);company=models.ForeignKey("organization.Company",on_delete=models.PROTECT);fund=models.ForeignKey(CashFund,on_delete=models.PROTECT,related_name="revaluations");revaluation_date=models.DateField();old_rate=models.DecimalField(max_digits=20,decimal_places=8);new_rate=models.DecimalField(max_digits=20,decimal_places=8);foreign_balance=models.DecimalField(max_digits=20,decimal_places=4);difference=models.DecimalField(max_digits=20,decimal_places=4);gl_reference=models.CharField(max_length=120,blank=True);created_by=models.ForeignKey("iam.UserAccount",on_delete=models.PROTECT);created_at=models.DateTimeField(auto_now_add=True)
    class Meta:db_table="cash_fx_revaluation";constraints=[models.UniqueConstraint(fields=("fund","revaluation_date"),name="uq_cash_fx_revaluation"),models.CheckConstraint(condition=Q(old_rate__gt=0,new_rate__gt=0),name="ck_cash_fx_rates")]
